package terraform

import (
	"bytes"
	"errors"
	"fmt"
	"mime"
	"net/http"
	"strconv"
	"strings"

	"github.com/go-chi/chi/v5"

	"github.com/openartifact/openartifact/internal/database/models"
	"github.com/openartifact/openartifact/internal/iocopy"
	"github.com/openartifact/openartifact/internal/presign"
	"github.com/openartifact/openartifact/internal/repotype"
)

// file is what a ticket resolves to: either a stored blob or generated bytes.
type file struct {
	name        string
	contentType string
	// blobKey, sha256 and size are set for stored archives.
	blobKey string
	sha256  string
	size    int64
	// data is set for generated files (checksums and their signature).
	data []byte
}

// handleTicketDownload serves GET/HEAD /terraform/dl/{ticket}/{filename}. The
// route is unauthenticated: the ticket is the authorisation. A refused ticket
// is always the same plain 403 so a client learns nothing about why.
func (h *HTTPHandler) handleTicketDownload(w http.ResponseWriter, r *http.Request) {
	t, err := decodeTicket(h.ticketKey, chi.URLParam(r, "ticket"), h.now())
	if err != nil {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	repo, err := h.DB.GetRepositoryByID(r.Context(), t.repoID)
	if err != nil {
		h.Log.Errorw("failed to resolve repo of a terraform ticket", "repo", t.repoID, "error", err)
		writeErrors(w, http.StatusInternalServerError, "internal error")

		return
	}

	if repo == nil || repo.Format != formatName {
		writeErrors(w, http.StatusNotFound, "not found")
		return
	}

	if repo.RepoType == repotype.Proxy {
		h.serveProxyTicket(w, r, repo, t, chi.URLParam(r, "filename"))
		return
	}

	f, err := h.resolveTicketFile(r, t)
	if err != nil {
		h.writeTicketError(w, repo.Name, err)
		return
	}

	// The ticket names its file; a request for another name is a different
	// URL and a client has no business building it.
	if f.name != chi.URLParam(r, "filename") {
		writeErrors(w, http.StatusNotFound, "not found")
		return
	}

	h.serveFile(w, r, repo, f)
}

var errTicketNotFound = errors.New("ticket target not found")

func (h *HTTPHandler) writeTicketError(w http.ResponseWriter, repoName string, err error) {
	switch {
	case errors.Is(err, errTicketNotFound):
		writeErrors(w, http.StatusNotFound, "not found")
	case errors.Is(err, errNoSigner):
		writeErrors(w, http.StatusServiceUnavailable, errNoSigner.Error())
	default:
		h.Log.Errorw("failed to resolve a terraform download", "repo", repoName, "error", err)
		writeErrors(w, http.StatusInternalServerError, "internal error")
	}
}

// resolveTicketFile looks up what the ticket names. Rows are resolved by
// coordinates at download time, so a version deleted after minting is gone.
func (h *HTTPHandler) resolveTicketFile(r *http.Request, t ticket) (file, error) {
	ctx := r.Context()

	switch t.kind {
	case kindModule:
		m, err := h.DB.GetTerraformModule(ctx, t.repoID, t.a, t.b, t.c)
		if err != nil {
			return file{}, fmt.Errorf("get module: %w", err)
		}

		if m == nil {
			return file{}, errTicketNotFound
		}

		return moduleFile(m), nil
	case kindProviderZip:
		osName, arch, _ := strings.Cut(t.c, "_")

		p, err := h.DB.GetTerraformProvider(ctx, t.repoID, t.a, t.b, osName, arch)
		if err != nil {
			return file{}, fmt.Errorf("get provider: %w", err)
		}

		if p == nil {
			return file{}, errTicketNotFound
		}

		return file{
			name: providerZipName(p.Type, p.Version, p.OS, p.Arch), contentType: "application/zip",
			blobKey: p.BlobKey, sha256: p.Checksum, size: p.SizeBytes,
		}, nil
	default:
		return h.checksumFile(r, t)
	}
}

func moduleFile(m *models.TerraformModule) file {
	contentType := "application/zip"
	if m.ArchiveExt == extTarGz {
		contentType = "application/gzip"
	}

	return file{
		name: moduleFileName(m.Name, m.System, m.Version, m.ArchiveExt), contentType: contentType,
		blobKey: m.BlobKey, sha256: m.Checksum, size: m.SizeBytes,
	}
}

// checksumFile builds a provider version's SHA256SUMS from its platforms, or
// the detached signature over it. They are generated per request: the set of
// platforms of a version can grow, and the signature is made with the key the
// repository has now.
func (h *HTTPHandler) checksumFile(r *http.Request, t ticket) (file, error) {
	rows, err := h.DB.ListTerraformProviderVersionPlatforms(r.Context(), t.repoID, t.a, t.b)
	if err != nil {
		return file{}, fmt.Errorf("list platforms: %w", err)
	}

	if len(rows) == 0 {
		return file{}, errTicketNotFound
	}

	entries := make([]sumEntry, 0, len(rows))
	for _, p := range rows {
		entries = append(entries, sumEntry{sha256: p.Checksum, filename: providerZipName(p.Type, p.Version, p.OS, p.Arch)})
	}

	sums := buildSHA256SUMS(entries)
	name := providerSumsName(t.a, t.b)

	if t.kind == kindProviderSums {
		return file{name: name, contentType: "text/plain; charset=utf-8", data: sums}, nil
	}

	signer, err := h.signerFor(r.Context(), t.repoID)
	if err != nil {
		return file{}, err
	}

	armored, err := signer.DetachedSign(bytes.NewReader(sums))
	if err != nil {
		return file{}, fmt.Errorf("sign checksums: %w", err)
	}

	sig, err := binarySignature(armored)
	if err != nil {
		return file{}, err
	}

	return file{name: name + ".sig", contentType: "application/octet-stream", data: sig}, nil
}

// serveFile writes f. The response is never cached: it is addressed by a
// ticket that expires, and generated files change with the version's platforms.
func (h *HTTPHandler) serveFile(w http.ResponseWriter, r *http.Request, repo *models.Repository, f file) {
	hdr := w.Header()
	hdr.Set("Cache-Control", "private, no-store")
	hdr.Set("Content-Type", f.contentType)
	hdr.Set("Content-Disposition", mime.FormatMediaType("attachment", map[string]string{"filename": f.name}))

	if f.data != nil {
		hdr.Set("Content-Length", strconv.Itoa(len(f.data)))
		w.WriteHeader(http.StatusOK)

		if r.Method != http.MethodHead {
			_, _ = w.Write(f.data)
		}

		return
	}

	hdr.Set("ETag", `"`+f.sha256+`"`)

	if r.Method == http.MethodHead {
		hdr.Set("Content-Length", strconv.FormatInt(f.size, 10))
		w.WriteHeader(http.StatusOK)

		return
	}

	if h.TryPresign(w, r, presign.Blob{
		SHA256: f.blobKey, Size: f.size, Filename: f.name, ContentType: f.contentType, Repository: repo,
	}) {
		return
	}

	blob, err := h.BlobStore.Get(r.Context(), f.blobKey)
	if err != nil {
		h.Log.Errorw("failed to get terraform blob", "key", f.blobKey, "error", err)
		hdr.Del("Content-Disposition")
		writeErrors(w, http.StatusInternalServerError, "internal error")

		return
	}
	defer func() { _ = blob.Close() }()

	hdr.Set("Content-Length", strconv.FormatInt(f.size, 10))
	w.WriteHeader(http.StatusOK)
	_, _ = iocopy.Copy(w, blob)
}
